CREATE TABLE fee_types (fee_type_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, organization_id BIGINT NOT NULL, fee_name VARCHAR(120) NOT NULL, description VARCHAR(500), is_recurring BOOLEAN NOT NULL DEFAULT FALSE, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by BIGINT NOT NULL, updated_at TIMESTAMP, updated_by BIGINT, CONSTRAINT uq_fee_type_name UNIQUE(organization_id,fee_name), CONSTRAINT fk_fee_type_org FOREIGN KEY(organization_id) REFERENCES organizations(organization_id));
CREATE TABLE fee_structures (fee_structure_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, organization_id BIGINT NOT NULL, academic_year_id BIGINT NOT NULL, class_id BIGINT NOT NULL, fee_type_id BIGINT NOT NULL, amount NUMERIC(14,2) NOT NULL, due_date DATE, due_day INTEGER, frequency VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by BIGINT NOT NULL, updated_at TIMESTAMP, updated_by BIGINT, CONSTRAINT uq_fee_structure UNIQUE(organization_id,academic_year_id,class_id,fee_type_id), CONSTRAINT ck_fee_amount CHECK(amount>0), CONSTRAINT ck_fee_due_day CHECK(due_day IS NULL OR due_day BETWEEN 1 AND 31), CONSTRAINT fk_fs_org FOREIGN KEY(organization_id) REFERENCES organizations(organization_id), CONSTRAINT fk_fs_year FOREIGN KEY(academic_year_id) REFERENCES academic_years(academic_year_id), CONSTRAINT fk_fs_class FOREIGN KEY(class_id) REFERENCES classes(class_id), CONSTRAINT fk_fs_type FOREIGN KEY(fee_type_id) REFERENCES fee_types(fee_type_id));
CREATE TABLE student_fees (student_fee_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, organization_id BIGINT NOT NULL, student_id BIGINT NOT NULL, academic_year_id BIGINT NOT NULL, class_id BIGINT, fee_structure_id BIGINT, fee_type_id BIGINT NOT NULL, fee_category VARCHAR(20) NOT NULL, total_amount NUMERIC(14,2) NOT NULL, discount_amount NUMERIC(14,2) NOT NULL DEFAULT 0, discount_reason VARCHAR(500), paid_amount NUMERIC(14,2) NOT NULL DEFAULT 0, balance_amount NUMERIC(14,2) NOT NULL, due_date DATE, payment_status VARCHAR(20) NOT NULL DEFAULT 'PENDING', status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by BIGINT NOT NULL, updated_at TIMESTAMP, updated_by BIGINT, version BIGINT NOT NULL DEFAULT 0, CONSTRAINT uq_student_structure UNIQUE(student_id,fee_structure_id), CONSTRAINT ck_student_fee_amounts CHECK(total_amount>0 AND discount_amount>=0 AND paid_amount>=0 AND balance_amount>=0), CONSTRAINT fk_sf_org FOREIGN KEY(organization_id) REFERENCES organizations(organization_id), CONSTRAINT fk_sf_student FOREIGN KEY(student_id) REFERENCES students(student_id), CONSTRAINT fk_sf_year FOREIGN KEY(academic_year_id) REFERENCES academic_years(academic_year_id), CONSTRAINT fk_sf_structure FOREIGN KEY(fee_structure_id) REFERENCES fee_structures(fee_structure_id), CONSTRAINT fk_sf_type FOREIGN KEY(fee_type_id) REFERENCES fee_types(fee_type_id));
CREATE INDEX idx_student_fee_pending ON student_fees(organization_id,payment_status,status); CREATE INDEX idx_student_fee_student ON student_fees(organization_id,student_id);
CREATE TABLE fee_payments (payment_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, organization_id BIGINT NOT NULL, student_fee_id BIGINT NOT NULL, student_id BIGINT NOT NULL, amount_paid NUMERIC(14,2) NOT NULL, refunded_amount NUMERIC(14,2) NOT NULL DEFAULT 0, payment_date DATE NOT NULL, payment_mode VARCHAR(30) NOT NULL, transaction_reference VARCHAR(150), receipt_number VARCHAR(100) NOT NULL, remarks VARCHAR(500), payment_status VARCHAR(30) NOT NULL DEFAULT 'COMPLETED', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by BIGINT NOT NULL, CONSTRAINT uq_fee_receipt UNIQUE(organization_id,receipt_number), CONSTRAINT ck_payment_amount CHECK(amount_paid>0 AND refunded_amount>=0 AND refunded_amount<=amount_paid), CONSTRAINT fk_fp_org FOREIGN KEY(organization_id) REFERENCES organizations(organization_id), CONSTRAINT fk_fp_fee FOREIGN KEY(student_fee_id) REFERENCES student_fees(student_fee_id), CONSTRAINT fk_fp_student FOREIGN KEY(student_id) REFERENCES students(student_id));
CREATE INDEX idx_fee_payment_date ON fee_payments(organization_id,payment_date); CREATE INDEX idx_fee_payment_student ON fee_payments(organization_id,student_id);
CREATE TABLE fee_refunds (refund_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, organization_id BIGINT NOT NULL, fee_payment_id BIGINT NOT NULL, refund_amount NUMERIC(14,2) NOT NULL, reason VARCHAR(500), refunded_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, refunded_by BIGINT NOT NULL, CONSTRAINT ck_refund_amount CHECK(refund_amount>0), CONSTRAINT fk_fr_org FOREIGN KEY(organization_id) REFERENCES organizations(organization_id), CONSTRAINT fk_fr_payment FOREIGN KEY(fee_payment_id) REFERENCES fee_payments(payment_id));
